-- V31.6 official academic catalog and study-plan synchronization
create extension if not exists pgcrypto;
create table if not exists public.academic_colleges(id uuid primary key default gen_random_uuid(),name_ar text not null unique,name_en text not null,sort_order int not null default 100,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.academic_departments(id uuid primary key default gen_random_uuid(),college_id uuid not null references public.academic_colleges(id) on delete cascade,name_ar text not null,name_en text not null,sort_order int not null default 100,active boolean not null default true,unique(college_id,name_ar));
create table if not exists public.academic_programs(id uuid primary key default gen_random_uuid(),college_id uuid not null references public.academic_colleges(id) on delete cascade,department_id uuid references public.academic_departments(id) on delete set null,name_ar text not null,name_en text not null,degree_ar text,degree_en text,official_url text,sort_order int not null default 100,active boolean not null default true,unique(college_id,name_ar,degree_ar));
create table if not exists public.course_programs(course_code text not null references public.courses(code) on update cascade on delete cascade,program_id uuid not null references public.academic_programs(id) on delete cascade,requirement_type text not null default 'major' check(requirement_type in ('university','college','major','elective')),semester_no int,source_url text,primary key(course_code,program_id,requirement_type));
alter table public.courses add column if not exists college_ar text; alter table public.courses add column if not exists college_en text; alter table public.courses add column if not exists department_ar text; alter table public.courses add column if not exists department_en text; alter table public.courses add column if not exists requirement_type text default 'major'; alter table public.courses add column if not exists source_url text;
insert into public.academic_colleges(name_ar,name_en,sort_order) values
('كلية العلوم والآداب','College of Arts and Sciences',10),('كلية الاقتصاد والإدارة ونظم المعلومات','College of Economics, Management and Information Systems',20),('كلية الهندسة والعمارة','College of Engineering and Architecture',30),('كلية العلوم الصحية','College of Health Sciences',40) on conflict(name_ar) do update set name_en=excluded.name_en,sort_order=excluded.sort_order,active=true;
