), deps as (insert into public.academic_departments(college_id,name_ar,name_en,sort_order) select distinct c.id,s.department_ar,s.department_en,100 from src s join public.academic_colleges c on c.name_ar=s.college_ar on conflict(college_id,name_ar) do update set name_en=excluded.name_en,active=true returning id,college_id,name_ar)
insert into public.academic_programs(college_id,department_id,name_ar,name_en,degree_ar,degree_en,official_url,sort_order) select c.id,d.id,s.program_ar,s.program_en,s.degree_ar,case s.degree_ar when 'دبلوم' then 'Diploma' when 'بكالوريوس' then 'Bachelor' when 'ماجستير' then 'Master' else s.degree_ar end,s.official_url,100 from src s join public.academic_colleges c on c.name_ar=s.college_ar join public.academic_departments d on d.college_id=c.id and d.name_ar=s.department_ar on conflict(college_id,name_ar,degree_ar) do update set department_id=excluded.department_id,name_en=excluded.name_en,degree_en=excluded.degree_en,official_url=excluded.official_url,active=true;
alter table public.academic_colleges enable row level security; alter table public.academic_departments enable row level security; alter table public.academic_programs enable row level security; alter table public.course_programs enable row level security;
drop policy if exists public_read_colleges on public.academic_colleges; create policy public_read_colleges on public.academic_colleges for select using(active);
drop policy if exists public_read_departments on public.academic_departments; create policy public_read_departments on public.academic_departments for select using(active);
drop policy if exists public_read_programs on public.academic_programs; create policy public_read_programs on public.academic_programs for select using(active);
drop policy if exists public_read_course_programs on public.course_programs; create policy public_read_course_programs on public.course_programs for select using(true);
grant select on public.academic_colleges,public.academic_departments,public.academic_programs,public.course_programs to anon,authenticated;
create unique index if not exists courses_code_unique_v316 on public.courses(code);
